class Solution:
    def shortestPath(self, grid: list[list[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        DIR = [0, 1, 0, -1, 0]
        queue = deque([(0, 0, 0, 0)])
        seen = set([0,0, 0])
        while queue:
            j = len(queue)
            for _ in range(j):
                r, c, obs, dist = queue.popleft()
                if r == m - 1 and c == n - 1:
                    return dist
                for i in range(4):
                    nr, nc, no, nd = r + DIR[i], c + DIR[i + 1], obs, dist + 1
                    if 0 <= nr < m and 0 <= nc < n:
                        if grid[nr][nc] == 1:
                            no += 1
                        if (nr, nc, no) not in seen and no <= k:
                            queue.append((nr, nc, no, nd))
                            seen.add((nr, nc, no))
        return -1
